```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <vector>
#include <algorithm>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("pogoda.txt");
    string data, miasto;
    int temp, opady;

    map<string, int> sumTemp, cntTemp, sumOpady, mrozne;
    string maxData, maxMiasto, minData, minMiasto;
    int maxTemp = -1000, minTemp = 1000;

    while (plik >> data >> miasto >> temp >> opady) {
        sumTemp[miasto] += temp;
        cntTemp[miasto]++;
        sumOpady[miasto] += opady;
        if (temp < 0) mrozne[miasto]++;
        if (temp > maxTemp) {
            maxTemp = temp; maxData = data; maxMiasto = miasto;
        }
        if (temp < minTemp) {
            minTemp = temp; minData = data; minMiasto = miasto;
        }
    }

    cout << fixed << setprecision(2);
    cout << "a) Statystyki miast:" << endl;
    for (auto &m : sumTemp) {
        cout << "   " << m.first << ": srednia temp = "
             << (double)m.second / cntTemp[m.first]
             << ", opady = " << sumOpady[m.first] << " mm" << endl;
    }

    cout << endl << "b) Ekstrema:" << endl;
    cout << "   Max: " << maxData << " " << maxMiasto << " (" << maxTemp << " C)" << endl;
    cout << "   Min: " << minData << " " << minMiasto << " (" << minTemp << " C)" << endl;

    vector<pair<int, string>> ranking;
    for (auto &m : sumOpady) ranking.push_back({m.second, m.first});
    sort(ranking.begin(), ranking.end(), [](auto &a, auto &b) {
        return a.first > b.first;
    });
    cout << endl << "c) Ranking opadow:" << endl;
    for (int i = 0; i < (int)ranking.size(); i++) {
        cout << "   " << i+1 << ". " << ranking[i].second << ": "
             << ranking[i].first << " mm" << endl;
    }

    cout << endl << "d) Dni ponizej zera:" << endl;
    for (auto &m : cntTemp) {
        cout << "   " << m.first << ": " << mrozne[m.first] << endl;
    }
    return 0;
}
```

